Let $u,v\in(0,1)$.  Then $0<a(u,v)<1$.  Consequently
  \begin{enumerate}
    \item if $p,t<1$ and $u<p$, $u<t$, then $R_1(u,v)>0$ (with $q=1$);
    \item if $p,t>0$ and $p<u$, $t<u$, then $R_1(u,v)<0$ (with $q=1$).
  \end{enumerate}

Let $F,G\colon\RR^2\to\RR$ be continuous on $[0,1]^2$ with
  \begin{enumerate}
    \item $F(0,v)>0$ for $v\in[0,1]$ and $G(u,0)>0$ for $u\in[0,1]$;
    \item for $v\in[0,1]$: if $G(1,v)=0$ then $F(1,v)<0$;
    \item for $u\in[0,1]$: if $F(u,1)=0$ then $G(u,1)<0$;
    \item $G(1,1)<0$.
  \end{enumerate}
  Then $F(u,v)=G(u,v)=0$ for some $(u,v)\in(0,1)^2$.

Let $0<u,v<1<q$, $L=L^{\mathrm{core}}(u,v)$ and
  $\alpha=\arcsin L_0$, $\beta=\arcsin L_3$, $\gamma=\arcsin(qL_1)$,
  $\delta=\arcsin(qL_2)$.  Then all $L_j>0$ and
  \begin{enumerate}
    \item $L_0^2+(vL_2)^2=1$, $L_3^2+(uL_1)^2=1$, $(qL_1)^2+(vL_3)^2=1$,
      $(qL_2)^2+(uL_0)^2=1$;
    \item the four angles lie in $(0,\pi/2)$ and
      $\cos\alpha=vL_2$, $\cos\beta=uL_1$, $\cos\gamma=vL_3$,
      $\cos\delta=uL_0$;
    \item $\tan\alpha=\dfrac{L_0}{vL_2}$, $\tan\beta=\dfrac{L_3}{uL_1}$,
      $\tan\gamma=\dfrac{qL_1}{vL_3}$, $\tan\delta=\dfrac{qL_2}{uL_0}$;
    \item $\tan\alpha\tan\delta=\tan\beta\tan\gamma=\dfrac q{uv}>1$;
    \item with $P=\tan\alpha/\tan\gamma$ and $Q=1/(\tan\gamma\tan\delta)$,
      \[
        \cos(\alpha+\beta)=\frac{Q-P^2}Q\cos\alpha\cos\beta,\qquad
        \frac{\cos(\gamma+\delta)}q=\frac{P(Q-1)}Q\cos\alpha\cos\beta .
      \]
  \end{enumerate}

