def affineRelation (p q r k T : ℝ) : ℝ :=
  -(p + 1) * (p - q) * (1 + T) + 2 * (p ^ 2 - q) * k -
    2 * p * (q - 1) * r

def turnTwo (p q B r k T : ℝ) : ℝ :=
  (p * B - q ^ 2) * T * (T - 2 * k + p * (T - 2 * r)) -
    q * (p + 1) * (B * T ^ 2 - p * (T - 2 * k) * (T - 2 * r))

