    \mathsf N&=(P+1)(P-Q)+2P(Q-1)r, &
    \mathsf H&=2kD_0+\mathsf N,
  \end{align*}
  \begin{align*}
    \operatorname{polyA}(r)&=2P^3r^2+(-3P^3+P^2Q+P^2+PQ)\,r
      +(P^3-P^2Q-P^2+Q^2),\\
    \operatorname{polyD}(r)&=(2P^2+2PQ-2P)\,r^2+(-P^2-PQ+3P-Q)\,r+(Q-P),\\
    \operatorname{polyC}(r)&=\mathcal B\,P\operatorname{polyD}(r)+Q\operatorname{polyA}(r).
  \end{align*}

