\Cref{lem:nrn_projective_H} gives $\mathsf H=0$;
  \cref{lem:nrn_projective_interval} gives $(P-Q)\tau=2kPr$,
  $\operatorname{polyC}(r)=0$ and $r_-<r<r_+$; \cref{lem:nrn_poly_signs}
  gives $\operatorname{polyC}(r)<0$.  Contradiction.

\Cref{thm:nrn_negative_zero} gives $u,v\in(0,1)$ with
  $L=L^{\mathrm{core}}(u,v)$ physical and $N(L)=0$;
  \cref{thm:nrn_incident_orthogonal_rank} gives surjectivity.
